  max_lag_days = 7, notes = '返回 GBK 编码；港股日期格式为 2026/10/22 16:08:42，解析器只取数字。港股收盘约 16:10，之前采集到的是盘中价。' WHERE name = '腾讯音乐港股股价（腾讯行情）';

